from .cpf import validar_cpf


def cadastrar_cliente(nome: str, cpf: str, email: str) -> Cliente:
    if not validar_cpf(cpf):
        raise CpfInvalido(cpf)
    return Cliente.objects.create(nome=nome, cpf=cpf, email=email)

